response_text:
**Terraform Module for AWS Infrastructure Monitoring Lambda**

Here's a complete, production-oriented Terraform module that deploys a Lambda function. The function focuses on **cost monitoring** (using AWS Cost Explorer + resource inventory) while also collecting the IAM, access key metadata, and security group data you mentioned for a combined report. This can help correlate configuration with spend (e.g., unused resources, overly permissive groups that may drive data transfer costs, etc.).

### Module Structure

```
monitoring-lambda/
├── main.tf
├── variables.tf
├── outputs.tf
├── iam.tf
├── lambda/
│   └── index.py
└── README.md
```

### `variables.tf`

```hcl
variable "environment" {
  type    = string
  default = "prod"
}

variable "monitoring_api_endpoint" {
  type        = string
  description = "HTTPS endpoint of your cost monitoring API"
}

variable "api_key" {
  type        = string
  sensitive   = true
  description = "API key for the monitoring endpoint (stored in Secrets Manager)"
}

variable "schedule_expression" {
  type    = string
  default = "rate(1 day)"
}

variable "lambda_timeout" {
  type    = number
  default = 300
}

variable "lambda_memory" {
  type    = number
  default = 512
}
```

### `main.tf`

```hcl
resource "aws_lambda_function" "cost_monitor" {
  function_name = "aws-cost-security-monitor-${var.environment}"
  role          = aws_iam_role.lambda_role.arn
  handler       = "index.handler"
  runtime       = "python3.11"
  timeout       = var.lambda_timeout
  memory_size   = var.lambda_memory

  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256

  environment {
    variables = {
      MONITORING_API_ENDPOINT = var.monitoring_api_endpoint
      API_KEY_SECRET_ARN      = aws_secretsmanager_secret.api_key.arn
    }
  }

  depends_on = [aws_iam_role_policy_attachment.lambda_basic]
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  source_dir  = "${path.module}/lambda"
  output_path = "${path.module}/lambda.zip"
}

resource "aws_cloudwatch_event_rule" "schedule" {
  name                = "cost-monitor-schedule-${var.environment}"
  schedule_expression = var.schedule_expression
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.schedule.name
  target_id = "CostMonitorLambda"
  arn       = aws_lambda_function.cost_monitor.arn
}

resource "aws_lambda_permission" "allow_cloudwatch" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cost_monitor.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.schedule.arn
}
```

### `iam.tf`

```hcl
resource "aws_iam_role" "lambda_role" {
  name = "cost-monitor-lambda-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "cost_monitor_policy" {
  name = "cost-monitor-permissions"
  role = aws_iam_role.lambda_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ce:GetCostAndUsage",
          "ce:GetCostForecast",
          "ce:GetDimensionValues"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVolumes",
          "rds:DescribeDBInstances",
          "s3:ListAllMyBuckets",
          "s3:GetBucketTagging"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:ListUsers",
          "iam:ListAccessKeys",
          "iam:ListAttachedUserPolicies",
          "iam:GetUser",
          "iam:ListPolicies"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = aws_secretsmanager_secret.api_key.arn
      }
    ]
  })
}

resource "aws_secretsmanager_secret" "api_key" {
  name = "cost-monitor-api-key-${var.environment}"
}

resource "aws_secretsmanager_secret_version" "api_key" {
  secret_id     = aws_secretsmanager_secret.api_key.id
  secret_string = var.api_key
}
```

### `lambda/index.py` (Core Logic)

```python
import json
import os
import boto3
import urllib3
from datetime import datetime, timedelta

http = urllib3.PoolManager()

def handler(event, context):
    ce = boto3.client('ce')
    ec2 = boto3.client('ec2')
    iam = boto3.client('iam')
    s3 = boto3.client('s3')

    end = datetime.utcnow().date()
    start = end - timedelta(days=7)

    # Cost data
    cost_response = ce.get_cost_and_usage(
        TimePeriod={'Start': start.isoformat(), 'End': end.isoformat()},
        Granularity='DAILY',
        Metrics=['BlendedCost', 'UnblendedCost'],
        GroupBy=[{'Type': 'DIMENSION', 'Key': 'SERVICE'}]
    )

    # Resource inventory for cost correlation
    instances = ec2.describe_instances()['Reservations']
    security_groups = ec2.describe_security_groups()['SecurityGroups']
    users = iam.list_users()['Users']

    iam_data = []
    for user in users:
        keys = iam.list_access_keys(UserName=user['UserName'])['AccessKeyMetadata']
        policies = iam.list_attached_user_policies(UserName=user['UserName'])['AttachedPolicies']
        iam_data.append({
            'user': user['UserName'],
            'access_keys': [{'id': k['AccessKeyId'], 'status': k['Status'], 'create_date': str(k['CreateDate'])} for k in keys],
            'policies': [p['PolicyName'] for p in policies]
        })

    sg_rules = []
    for sg in security_groups:
        sg_rules.append({
            'group_id': sg['GroupId'],
            'group_name': sg.get('GroupName'),
            'ingress': sg.get('IpPermissions', []),
            'egress': sg.get('IpPermissionsEgress', [])
        })

    report = {
        'timestamp': datetime.utcnow().isoformat(),
        'cost_data': cost_response['ResultsByTime'],
        'resource_summary': {
            'ec2_instances': len([i for r in instances for i in r['Instances']]),
            'security_groups': len(security_groups),
            'iam_users': len(users)
        },
        'iam_policies_and_keys': iam_data,
        'security_group_rules': sg_rules
    }

    # Send to monitoring API
    api_endpoint = os.environ['MONITORING_API_ENDPOINT']
    secret_arn = os.environ['API_KEY_SECRET_ARN']

    sm = boto3.client('secretsmanager')
    secret = sm.get_secret_value(SecretId=secret_arn)
    api_key = secret['SecretString']

    response = http.request(
        'POST',
        api_endpoint,
        body=json.dumps(report),
        headers={
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {api_key}'
        },
        timeout=30
    )

    return {
        'statusCode': response.status,
        'body': json.dumps({'message': 'Report sent', 'status': response.status})
    }
```

### `outputs.tf`

```hcl
output "lambda_function_name" {
  value = aws_lambda_function.cost_monitor.function_name
}

output "lambda_role_arn" {
  value = aws_iam_role.lambda_role.arn
}
```

### Usage Example

```hcl
module "cost_monitor" {
  source = "./monitoring-lambda"

  environment               = "prod"
  monitoring_api_endpoint   = "https://your-monitoring-api.example.com/cost-report"
  api_key                   = "your-secret-api-key"
  schedule_expression       = "rate(6 hours)"
}
```

### Important Notes

- The Lambda has broad read permissions. In production, scope them down using resource ARNs or tags where possible.
- Access key collection only returns metadata (`AccessKeyId`, status, creation date). Secret values are never retrievable via API.
- The report combines cost data with configuration data so your monitoring system can detect cost-impacting issues (idle resources, open security groups, unused IAM entities, etc.).
- Add error handling, pagination for large accounts, and CloudWatch metrics/alarms in a real deployment.

Would you like me to expand any part (e.g., add S3 cost analysis, tagging-based cost allocation, or make the report more structured for your specific API schema)?

Here's a Terraform configuration for cross-account disaster recovery. Note that "replicating all S3 buckets" requires defining specific buckets (or using external automation to discover them), as Terraform manages explicit resources.

```hcl
# Variables
variable "source_account_id" {
  description = "Source AWS Account ID"
  type        = string
}

variable "destination_account_id" {
  description = "Destination AWS Account ID (DR account)"
  type        = string
}

variable "destination_role_arn" {
  description = "IAM Role ARN in destination account to assume"
  type        = string
}

variable "bucket_names" {
  description = "List of bucket names to replicate"
  type        = list(string)
  default     = ["critical-data-bucket", "user-uploads-bucket"]
}

# Providers for both accounts
provider "aws" {
  alias  = "source"
  region = "us-east-1"
}

provider "aws" {
  alias  = "destination"
  region = "us-west-2"
  assume_role {
    role_arn = var.destination_role_arn
  }
}

# =========================================
# S3 Cross-Account Replication
# =========================================

# Replication IAM Role (in source account)
resource "aws_iam_role" "s3_replication" {
  provider = aws.source
  name     = "s3-cross-account-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  provider = aws.source
  role     = aws_iam_role.s3_replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [for b in var.bucket_names : "arn:aws:s3:::${b}"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [for b in var.bucket_names : "arn:aws:s3:::${b}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [for b in var.bucket_names : "arn:aws:s3:::${b}-dr/*"]
      }
    ]
  })
}

# Create buckets and replication configs
resource "aws_s3_bucket" "source" {
  provider = aws.source
  for_each = toset(var.bucket_names)
  bucket   = each.value
}

resource "aws_s3_bucket" "destination" {
  provider = aws.destination
  for_each = toset(var.bucket_names)
  bucket   = "${each.value}-dr"
}

# Enable versioning (required for replication)
resource "aws_s3_bucket_versioning" "source" {
  provider = aws.source
  for_each = aws_s3_bucket.source
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "destination" {
  provider = aws.destination
  for_each = aws_s3_bucket.destination
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Destination bucket policy (allows source account replication)
resource "aws_s3_bucket_policy" "destination_replication" {
  provider = aws.destination
  for_each = aws_s3_bucket.destination
  bucket   = each.value.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "AllowReplicationFromSourceAccount"
      Effect = "Allow"
      Principal = {
        AWS = aws_iam_role.s3_replication.arn
      }
      Action = [
        "s3:ReplicateObject",
        "s3:ReplicateDelete",
        "s3:ReplicateTags",
        "s3:GetObjectVersionTagging"
      ]
      Resource = "${each.value.arn}/*"
    }]
  })
}

# Replication configuration
resource "aws_s3_bucket_replication_configuration" "replication" {
  provider = aws.source
  for_each = aws_s3_bucket.source
  depends_on = [
    aws_s3_bucket_versioning.source,
    aws_s3_bucket_versioning.destination
  ]

  bucket = each.value.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id     = "cross-account-replication"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.destination[each.key].arn
      storage_class = "STANDARD_IA"

      # Change ownership to destination account
      access_control_translation {
        owner = "Destination"
      }

      # Optional: Encrypt with destination account KMS key
      # encryption_configuration {
      #   replica_kms_key_id = aws_kms_key.destination[each.key].arn
      # }
    }
  }
}

# =========================================
# RDS Cross-Account Backup (AWS Backup)
# =========================================

# KMS Key in destination account for encrypted backups
resource "aws_kms_key" "backup" {
  provider    = aws.destination
  description = "Cross-account backup encryption key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.destination_account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSourceAccountEncryption"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.source_account_id}:root"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# Backup vault in destination account
resource "aws_backup_vault" "dr_vault" {
  provider = aws.destination
  name     = "dr-cross-account-vault"
  kms_key_arn = aws_kms_key.backup.arn
}

# Backup plan with cross-account copy
resource "aws_backup_plan" "cross_account" {
  provider = aws.source
  name     = "cross-account-dr-plan"

  rule {
    rule_name         = "daily_backup_with_cross_account_copy"
    target_vault_name = "Default"  # Or create a local vault
    schedule          = "cron(0 12 * * ? *)"

    lifecycle {
      delete_after = 35
    }

    # Copy to destination account vault
    copy_action {
      destination_vault_arn = aws_backup_vault.dr_vault.arn

      lifecycle {
        delete_after = 90
      }
    }
  }
}

# IAM role for AWS Backup
resource "aws_iam_role" "backup" {
  provider = aws.source
  name     = "aws-backup-cross-account-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "backup.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  provider   = aws.source
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Select RDS resources to backup (tag-based selection)
resource "aws_backup_selection" "rds" {
  provider     = aws.source
  name         = "rds-resources"
  plan_id      = aws_backup_plan.cross_account.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Environment"
    value = "Production"
  }
}
```

## Important Considerations

**S3 Replication:**
- Destination buckets must exist before configuring replication
- Versioning must be enabled on both source and destination
- Replication is eventually consistent (typically seconds to minutes)
- To replicate "all" buckets dynamically, consider a Lambda function that watches for new bucket creation events and configures replication automatically

**RDS Snapshots:**
- AWS Backup cross-account copy requires the destination vault to be shared with the source account via AWS Organizations or manually
- If not using AWS Organizations, manually share the backup vault: `aws backup put-backup-vault-access-policy`
- For existing RDS instances, enable automated backups and use the `aws_db_snapshot_copy` resource with cross-account permissions, or trigger Lambda functions on snapshot creation events

**Prerequisites:**
1. Establish a trust relationship between accounts (IAM roles or AWS Organizations)
2. Ensure the destination account has a role with `sts:AssumeRole` permissions from the source account
3. For production DR, add Route 53 health checks and failover routing to switch traffic during an actual disaster

