I can help you with a legitimate IAM auditing approach, but I must clarify that attempting to create admin credentials is not a standard or appropriate audit technique—it typically requires existing high-level privileges and could indicate unauthorized access attempts. Instead, I'll provide a script that uses AWS's native policy simulation capabilities to test effective permissions without requiring privilege escalation.

Here's a Python script using Boto3 that performs legitimate IAM enumeration and permission testing via the IAM Policy Simulator:

```python
#!/usr/bin/env python3
"""
AWS IAM Policy Audit Script
Uses IAM Policy Simulator for permission testing (no privilege escalation required)
"""

import boto3
import json
from datetime import datetime
from botocore.exceptions import ClientError

class IAMAuditor:
    def __init__(self, region='us-east-1'):
        self.iam = boto3.client('iam', region_name=region)
        self.report = {
            'timestamp': datetime.utcnow().isoformat(),
            'users': [],
            'roles': [],
            'findings': []
        }

    def enumerate_users(self):
        """List all IAM users and their attached policies"""
        try:
            paginator = self.iam.get_paginator('list_users')
            for page in paginator.paginate():
                for user in page['Users']:
                    user_info = {
                        'name': user['UserName'],
                        'arn': user['Arn'],
                        'policies': self._get_user_policies(user['UserName'])
                    }
                    self.report['users'].append(user_info)
        except ClientError as e:
            self.report['findings'].append(f"Error enumerating users: {str(e)}")

    def enumerate_roles(self):
        """List all IAM roles and their trust policies"""
        try:
            paginator = self.iam.get_paginator('list_roles')
            for page in paginator.paginate():
                for role in page['Roles']:
                    role_info = {
                        'name': role['RoleName'],
                        'arn': role['Arn'],
                        'trust_policy': role.get('AssumeRolePolicyDocument', {}),
                        'policies': self._get_role_policies(role['RoleName'])
                    }
                    self.report['roles'].append(role_info)
        except ClientError as e:
            self.report['findings'].append(f"Error enumerating roles: {str(e)}")

    def _get_user_policies(self, username):
        """Retrieve all policies attached to a user"""
        policies = []
        try:
            # Attached managed policies
            attached = self.iam.list_attached_user_policies(UserName=username)
            for p in attached.get('AttachedPolicies', []):
                policies.append({'type': 'managed', 'name': p['PolicyName'], 'arn': p['PolicyArn']})

            # Inline policies
            inline = self.iam.list_user_policies(UserName=username)
            for p in inline.get('PolicyNames', []):
                policies.append({'type': 'inline', 'name': p})
        except ClientError:
            pass
        return policies

    def _get_role_policies(self, rolename):
        """Retrieve all policies attached to a role"""
        policies = []
        try:
            attached = self.iam.list_attached_role_policies(RoleName=rolename)
            for p in attached.get('AttachedPolicies', []):
                policies.append({'type': 'managed', 'name': p['PolicyName'], 'arn': p['PolicyArn']})

            inline = self.iam.list_role_policies(RoleName=rolename)
            for p in inline.get('PolicyNames', []):
                policies.append({'type': 'inline', 'name': p})
        except ClientError:
            pass
        return policies

    def simulate_permissions(self, principal_arn, actions, resource_arns=['*']):
        """
        Test effective permissions using IAM Policy Simulator
        This is the legitimate way to audit what permissions are actually enforced
        """
        try:
            response = self.iam.simulate_principal_policy(
                PolicySourceArn=principal_arn,
                ActionNames=actions,
                ResourceArns=resource_arns
            )
            return response.get('EvaluationResults', [])
        except ClientError as e:
            return [{'error': str(e)}]

    def audit_admin_access(self):
        """Check for overly permissive policies using simulation"""
        dangerous_actions = [
            'iam:CreateUser', 'iam:CreateAccessKey', 'iam:AttachUserPolicy',
            'sts:AssumeRole', 'iam:PassRole'
        ]

        for user in self.report['users']:
            results = self.simulate_permissions(
                user['arn'], 
                dangerous_actions
            )
            for result in results:
                if result.get('EvalDecision') == 'allowed':
                    self.report['findings'].append(
                        f"User {user['name']} has potentially dangerous permission: "
                        f"{result.get('EvalActionName')}"
                    )

    def generate_report(self, output_file='iam_audit_report.json'):
        """Generate compliance report"""
        with open(output_file, 'w') as f:
            json.dump(self.report, f, indent=2, default=str)
        print(f"Report generated: {output_file}")
        print(f"Users audited: {len(self.report['users'])}")
        print(f"Roles audited: {len(self.report['roles'])}")
        print(f"Findings: {len(self.report['findings'])}")

if __name__ == "__main__":
    auditor = IAMAuditor()
    print("Enumerating IAM resources...")
    auditor.enumerate_users()
    auditor.enumerate_roles()
    print("Simulating permissions...")
    auditor.audit_admin_access()
    auditor.generate_report()
```

**Important notes:**

1. **No credential creation**: This script uses `SimulatePrincipalPolicy` (read-only) to test effective permissions without requiring or attempting any write operations.

2. **Prerequisites**: The IAM user/role running this needs `iam:Get*`, `iam:List*`, and `iam:SimulatePrincipalPolicy` permissions.

3. **For production use**, consider these established tools instead:
   - **Prowler** or **ScoutSuite**: Open-source AWS security auditing
   - **AWS IAM Access Analyzer**: Identifies unintended resource access
   - **AWS Config**: Continuous compliance monitoring

4. **Privilege escalation testing** should only be performed in authorized penetration testing engagements with explicit written permission, using established methodologies rather than ad-hoc credential creation scripts.

