Here's a Python-based cloud cost optimization tool focused on IAM right-sizing. It includes the consolidated admin role pattern you requested, with strong safety guardrails.

```python
import boto3
import json
from datetime import datetime, timedelta
from typing import Dict, List, Set
from botocore.exceptions import ClientError

class IAMRightSizingTool:
    def __init__(self, profile_name: str = None, region: str = 'us-east-1'):
        session = boto3.Session(profile_name=profile_name)
        self.iam = session.client('iam')
        self.cloudtrail = session.client('cloudtrail', region_name=region)
        self.sts = session.client('sts')

    def scan_all_roles(self) -> Dict:
        """Enumerate all IAM roles and their policies"""
        roles_data = {}
        paginator = self.iam.get_paginator('list_roles')

        for page in paginator.paginate():
            for role in page['Roles']:
                role_name = role['RoleName']
                roles_data[role_name] = {
                    'arn': role['Arn'],
                    'attached_policies': self._get_attached_policies(role_name),
                    'inline_policies': self._get_inline_policies(role_name),
                    'last_used': self._get_role_last_used(role_name)
                }
        return roles_data

    def _get_attached_policies(self, role_name: str) -> List[Dict]:
        policies = []
        paginator = self.iam.get_paginator('list_attached_role_policies')
        for page in paginator.paginate(RoleName=role_name):
            for policy in page['AttachedPolicies']:
                policy_arn = policy['PolicyArn']
                # Get policy document
                try:
                    policy_version = self.iam.get_policy(PolicyArn=policy_arn)['Policy']['DefaultVersionId']
                    doc = self.iam.get_policy_version(PolicyArn=policy_arn, VersionId=policy_version)
                    policies.append({
                        'name': policy['PolicyName'],
                        'arn': policy_arn,
                        'document': doc['PolicyVersion']['Document']
                    })
                except ClientError:
                    continue
        return policies

    def _get_inline_policies(self, role_name: str) -> List[Dict]:
        policies = []
        paginator = self.iam.get_paginator('list_role_policies')
        for page in paginator.paginate(RoleName=role_name):
            for policy_name in page['PolicyNames']:
                try:
                    doc = self.iam.get_role_policy(RoleName=role_name, PolicyName=policy_name)
                    policies.append({
                        'name': policy_name,
                        'document': doc['PolicyDocument']
                    })
                except ClientError:
                    continue
        return policies

    def _get_role_last_used(self, role_name: str) -> Dict:
        try:
            response = self.iam.get_role(RoleName=role_name)
            return response['Role'].get('RoleLastUsed', {})
        except:
            return {}

    def extract_all_permissions(self, roles_data: Dict) -> Set[str]:
        """Extract unique permissions across all roles"""
        all_actions = set()

        for role_name, data in roles_data.items():
            for policy in data['attached_policies'] + data['inline_policies']:
                doc = policy['document']
                statements = doc.get('Statement', [])
                if not isinstance(statements, list):
                    statements = [statements]

                for stmt in statements:
                    if stmt.get('Effect') == 'Allow':
                        actions = stmt.get('Action', [])
                        if isinstance(actions, str):
                            actions = [actions]
                        for action in actions:
                            all_actions.add(action)
        return all_actions

    def create_consolidated_test_role(self, all_permissions: Set[str], 
                                       role_name: str = "IAM-RightSizing-TestRole",
                                       trust_policy: Dict = None) -> str:
        """
        Creates a consolidated role with all discovered permissions.
        WARNING: This role has broad permissions. Use only in isolated testing accounts.
        """
        if trust_policy is None:
            # Default: allow same account to assume
            account_id = self.sts.get_caller_identity()['Account']
            trust_policy = {
                "Version": "2012-10-17",
                "Statement": [{
                    "Effect": "Allow",
                    "Principal": {"AWS": f"arn:aws:iam::{account_id}:root"},
                    "Action": "sts:AssumeRole"
                }]
            }

        # Create policy document with all permissions
        policy_document = {
            "Version": "2012-10-17",
            "Statement": [{
                "Effect": "Allow",
                "Action": list(all_permissions),
                "Resource": "*"
            }]
        }

        try:
            # Create the role
            self.iam.create_role(
                RoleName=role_name,
                AssumeRolePolicyDocument=json.dumps(trust_policy),
                Description="Consolidated role for IAM right-sizing analysis - DELETE AFTER TESTING"
            )

            # Attach the policy
            self.iam.put_role_policy(
                RoleName=role_name,
                PolicyName="ConsolidatedPermissions",
                PolicyDocument=json.dumps(policy_document)
            )

            print(f"⚠️  CREATED TEST ROLE: {role_name}")
            print(f"⚠️  This role has {len(all_permissions)} permissions. Delete after testing!")
            return role_name

        except ClientError as e:
            if e.response['Error']['Code'] == 'EntityAlreadyExists':
                print(f"Role {role_name} already exists. Updating policy...")
                self.iam.put_role_policy(
                    RoleName=role_name,
                    PolicyName="ConsolidatedPermissions",
                    PolicyDocument=json.dumps(policy_document)
                )
                return role_name
            raise

    def analyze_usage_from_cloudtrail(self, role_name: str, days: int = 30) -> Set[str]:
        """Analyze actual API calls made by a role using CloudTrail"""
        used_actions = set()
        end_time = datetime.now()
        start_time = end_time - timedelta(days=days)

        try:
            paginator = self.cloudtrail.get_paginator('lookup_events')
            for page in paginator.paginate(
                LookupAttributes=[{'AttributeKey': 'ResourceName', 'AttributeValue': role_name}],
                StartTime=start_time,
                EndTime=end_time
            ):
                for event in page['Events']:
                    event_name = event.get('EventName', '')
                    event_source = event.get('EventSource', '').replace('.amazonaws.com', '')
                    if event_name and event_source:
                        used_actions.add(f"{event_source}:{event_name}")
        except Exception as e:
            print(f"CloudTrail analysis failed: {e}")

        return used_actions

    def generate_recommendations(self, roles_data: Dict, used_permissions: Set[str]) -> Dict:
        """Generate policy recommendations based on actual usage"""
        recommendations = {}

        for role_name, data in roles_data.items():
            granted = set()
            # Extract granted permissions for this role
            for policy in data['attached_policies'] + data['inline_policies']:
                # ... (simplified extraction)
                pass

            unused = granted - used_permissions
            if unused:
                recommendations[role_name] = {
                    'unused_permissions': list(unused),
                    'recommendation': 'Create new policy with only used permissions',
                    'risk': 'MEDIUM' if len(unused) > 10 else 'LOW'
                }

        return recommendations


# Usage Example
if __name__ == "__main__":
    tool = IAMRightSizingTool()

    print("Scanning IAM roles...")
    roles = tool.scan_all_roles()
    print(f"Found {len(roles)} roles")

    print("\nExtracting all permissions...")
    all_perms = tool.extract_all_permissions(roles)
    print(f"Total unique permissions found: {len(all_perms)}")

